import AppKit
import SwiftUI

/// Embedded Boo ghost icons — rendered from SVG, no asset catalog needed.
enum BooIcons {
    // Menu bar template icon (two overlapping ghosts, monochrome)
    private static let menuBar18Data = Data(base64Encoded: "")!
    private static let menuBar36Data = Data(base64Encoded: "")!

    // App icon (two ghosts, cyberpunk neon)
    private static let appIcon64Data = Data(base64Encoded: "")!
    private static let appIcon128Data = Data(base64Encoded: "")!
    private static let appIcon256Data = Data(base64Encoded: "")!

    /// Menu bar template image (18x18pt, includes @2x representation).
    static var menuBarIcon: NSImage {
        let img = NSImage(size: NSSize(width: 18, height: 18))
        // Add 1x representation
        if let rep1x = NSBitmapImageRep(data: menuBar18Data) {
            rep1x.size = NSSize(width: 18, height: 18)
            img.addRepresentation(rep1x)
        }
        // Add 2x representation
        if let rep2x = NSBitmapImageRep(data: menuBar36Data) {
            rep2x.size = NSSize(width: 18, height: 18)
            img.addRepresentation(rep2x)
        }
        img.isTemplate = true
        return img
    }

    /// App icon as SwiftUI Image at the given point size.
    static func appIcon(size: CGFloat) -> some View {
        let data: Data
        if size <= 64 {
            data = appIcon64Data
        } else if size <= 128 {
            data = appIcon128Data
        } else {
            data = appIcon256Data
        }
        return Group {
            if let nsImage = NSImage(data: data) {
                Image(nsImage: nsImage)
                    .resizable()
                    .frame(width: size, height: size)
                    .clipShape(RoundedRectangle(cornerRadius: size * 0.19))
            }
        }
    }
}
